SELECT location, CASE WHEN budget >= 4302000 THEN 'high' WHEN budget >= 1047000 THEN 'mid' ELSE 'low' END AS budget_bucket, ROUND((100 * SUM(CASE WHEN dept_name = 'HR' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_hr, MAX(budget) AS max_budget FROM departments WHERE budget BETWEEN 1702000 AND 3829000 GROUP BY 1, 2 HAVING ROUND((100 * SUM(CASE WHEN dept_name = 'HR' THEN 1 ELSE 0 END)) / COUNT(*), 1) > 71 ORDER BY max_budget DESC, location, budget_bucket LIMIT 5
